using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakIndependentTailInterior;
internal sealed class EndpointDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Collision-free low-bit UXWV first ear", H("Independent unbounded gaps and the original physical source"),
        Blocks(Describe.Lean(DescribeId.Create("independent-tail-interior-first-ear"),
            DeclarationHandle.Create("D5/S3/Combinatorics/Circle/FourNegative/SecondPeakIndependentTailInterior/Endpoint.actualSource_independent_tail_interior_first_ear"),
            H("One old word and its literal cut-zero ear"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("For all independent naturals a,b,c,d with c>=2, d>=c+2, a>=c+d+3 and b>=a+1, put k=a+b+c+d and A=1+2^a+2^(a+b)+2^(a+b+c). The conclusion supplies one sigma of Fin(k) with OriginalOrder(k,A,sigma) and OriginalOrder(k+1,2A,earWord(k,sigma,0)). These full predicates include the exact physical permutation, zero total and both bounds for every natural take-prefix. No allocation, certificate, altered seed, orbit relabeling or existential cut is a premise.")),
                Paragraph(Text("Set z=2^c,w=2^d,t=2^(a-c-d-3),q=2^(b-a-1),x=8tzw and y=2qx. Native disjoint bit supports implement the four mask banks with fixed P=1 and terminal order U,X,W,V. The U selector is w/(2z)-1 at c=2 and w/(2z) at c>=3. The X donors t(w+3z+2),tzw and bit zero are disjoint even at t=1 and d=c+2. W includes the empty low bank at q=1.")),
                Paragraph(Text("The two exhaustive charts z=4 and z=Z+8 express the actual accumulated seams and peak slacks as positive polynomials in nonnegative Z,V,T,R. Exact source recurrences and weighted decoded masks connect those identities to both original rows. Positivity of the first bank moves the fresh A to its literal first position while preserving all later heights, so the old physical sigma is unchanged. The general four-gap Circle J question outside this domain remains open. The construction and polynomial identities are mathematical inputs; no literature novelty or full Circle J claim is made."))), DescribeRole.Theorem)), []));
}
